// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/domain/help.ts`. Edit the source and run `just generate`.
// The help texts of the `minispec` CLI. Each text has examples, as <https://clig.dev/> asks.

import {
  COMMAND_HELP,
  COMMAND_TABLE,
  GLOBAL_FLAGS,
  MAIN_HELP,
} from "../prompts.ts";

export interface CommandHelp {
  readonly usage: string;
  readonly summary: string;
  readonly flags: readonly string[];
  readonly examples: readonly string[];
}

export const COMMANDS: Readonly<Record<string, CommandHelp>> = COMMAND_TABLE;

const indented = (lines: readonly string[]): string =>
  lines.map((l) => `  ${l}`).join("\n");

const GLOBAL = GLOBAL_FLAGS.split("\n");

/** The help of one command. */
export const commandHelp = (name: string): string => {
  const c = COMMANDS[name];
  if (c === undefined) return "";
  return `${COMMAND_HELP({
    usage: c.usage,
    summary: c.summary,
    flags: indented([...c.flags, ...GLOBAL]),
    examples: indented(c.examples),
  })}\n`;
};

/** The help of the CLI. */
export const mainHelp = (): string =>
  `${MAIN_HELP({
    commands: indented(
      Object.entries(COMMANDS).map(
        ([name, c]) => `${name.padEnd(9)}${c.summary}`,
      ),
    ),
    flags: indented(GLOBAL),
  })}\n`;
